#!/bin/sh
# Read the random passwords generated by the compose secrets service on first start, build the connection strings, then start the service.
set -eu
export DATABASE_URL="postgresql://health:$(cat /secrets/pg_password)@db:5432/health"
export DATABASE_URL_RO="postgresql://health_ro:$(cat /secrets/ro_password)@db:5432/health"
export BETTER_AUTH_SECRET="$(cat /secrets/auth_secret)"
exec "$@"
